(() => {
  'use strict';
  const D = window.KEYNOTE;
  const $ = s => document.querySelector(s);
  const esc = x => String(x ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const lines = x => esc(x).replace(/\n/g,'<br>');
  const words = x => x.trim().split(/\s+/).filter(Boolean).length;
  const spoken = x => x.replaceAll('ГК РФ','Гражданского кодекса Российской Федерации').replaceAll('434.1','четыреста тридцать четыре точка один').replaceAll('179','сто семьдесят девять').replaceAll('2016','две тысячи шестнадцатого').replaceAll('№','номер').replace(/([А-Я])\.([А-Я])\./g,'$1 $2').replaceAll('de lege ferenda','де леге ференда');
  const steps = D.scenes.flatMap((s,scene)=>s.steps.map((t,step)=>({...t,scene,step,spokenWords:words(spoken(t.speech))})));
  const totalWords=steps.reduce((n,t)=>n+t.spokenWords,0), pauses=steps.reduce((n,t)=>n+t.pause,0);
  let cursor=0; steps.forEach(t=>{t.start=cursor;t.duration=(600-pauses)*t.spokenWords/totalWords+t.pause;cursor+=t.duration;});
  const time = s => {const n=Math.max(0,Math.floor(s));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');};
  const stepData=(s=state)=>steps.find(t=>t.scene===s.scene&&t.step===s.step);
  const theme = scene => [0,4,7].includes(scene)?'paper':'';
  const header=(scene,step)=>`<div class="scene-eyebrow"><span class="scene-index">${String(scene+1).padStart(2,'0')}</span><span>${esc(D.scenes[scene].title)}</span></div><div class="scene-line"></div><div class="scene-ref">${esc(D.scenes[scene].ref)}</div><div class="scene-page">${step+1} / ${D.scenes[scene].steps.length}</div>`;
  const open = step => step===0 ? `<div class="opening-geometry" aria-hidden="true">${'<i class="ring"></i>'.repeat(4)}<i class="cut"></i></div><div class="letter-stack"><h1 class="open-word"><span class="word-cut">Добросовестность</span></h1><div class="open-support"><span class="rulemark"></span>предполагается</div></div><div class="foot-author">Антонов Михаил Александрович<small>Поволжский юридический конгресс · Ульяновск · 10.10.2026</small></div>` : `<div class="opening-geometry exception" aria-hidden="true">${'<i class="ring"></i>'.repeat(4)}<i class="cut"></i></div><div class="letter-stack"><h1 class="open-word smaller"><span class="word-cut">Недобросовестность</span></h1><div class="open-support">тоже может предполагаться</div></div><div class="exception-kicker">Специальное правило</div>`;
  const levels = step => {
    const title=['Нормативный\nстандарт','Исходная\nоценка поведения','Специальное\nисключение'][step];
    return `<div class="level-intro">${lines(title)}</div><div class="level-rail"></div><div class="levels"><div class="legal-plane p1 ${step===0?'active':''}"><span>Принцип</span><small>п. 3 ст. 1</small></div><div class="legal-plane p2 ${step<1?'dormant':'active'}"><span>Презумпция</span><small>п. 5 ст. 10</small></div><div class="legal-plane p3 ${step<2?'dormant':'active'}"><span class="cut-label">Недобросовестность</span></div></div><div class="level-caption">${step===2?'Исключение из <em>предположения</em>':step===1?'Предполагаемое соблюдение стандарта':'Должное поведение'}</div>`;
  };
  const negotiations = step => {
    const copy=[['Прекращение\nпереговоров','Само по себе недостаточно'],['Неполная или\nнедостоверная информация','Включая подлежащее сообщению умолчание'],['Внезапное и неоправданное\nпрекращение переговоров','Другая сторона не могла разумно ожидать']];
    let txt = step===3 ? `<h1 class="shift-claim"><span class="word-cut">Ответчик доказывает</span>добросовестность</h1><div class="shift-sub">Установлено основание подпункта 1 или 2</div>` : `<div class="negotiation-copy"><h1 class="medium"><span class="word-cut">${lines(copy[step][0])}</span></h1></div><div class="negotiation-note">${esc(copy[step][1])}</div>`;
    return `<div class="number-watermark" aria-hidden="true">434.1</div>${step===1||step===2?`<div class="fact-index">ФАКТЫ-ОСНОВАНИЯ · ПОДПУНКТ ${step}</div>`:''}${txt}<div class="risk-system"><div class="risk-line"></div><div class="risk-token ${step===3?'right':''}"></div><span class="risk-owner left ${step!==3?'active':''}">ИСТЕЦ</span><span class="risk-owner right ${step===3?'active':''}">ОТВЕТЧИК</span><span class="risk-caption">${step===3?'СПЕЦИАЛЬНЫЙ РЕЖИМ':step>0?'СПЕЦИАЛЬНОЕ ОСНОВАНИЕ':'ОБЩИЙ РЕЖИМ'}</span></div>`;
  };
  const boundary = step => step===2 ? `<div class="two-scales"><div class="scale-column"><h1 class="medium">Введение\nправила</h1><p>Обоснование специализации</p></div><div class="scale-column"><h1 class="medium">Применение\nправила</h1><p class="accent">Установленные факты-основания</p></div></div>` : `<div class="boundary-heading"><h1 class="large"><span class="word-cut">${step===0?'Трудность<br>доказывания':'Цель<br>и средство'}</span></h1></div><div class="boundary-annotation">${step===0?'Недостаточное основание<br>для исключения':'Соответствие распределения риска<br>назначению защищающей нормы'}</div><div class="boundary-diagram" aria-hidden="true"><div class="boundary-strata ${step===1?'allowed':''}">${'<i></i>'.repeat(6)}<div class="gate"></div><div class="bar"></div></div></div>`;
  const mechanism = step => {
    const titles=['Результат\nзащиты','Вспомогательное\nсредство','Другие условия\nпроверяются'];
    const notes=['Защитное последствие','Изменение доказательственной позиции','Убытки · причинная связь'];
    return `<div class="mechanism-copy"><h1 class="medium"><span class="word-cut">${lines(titles[step])}</span></h1><p class="mechanism-note">${esc(notes[step])}</p></div><div class="mechanism-drawing"><svg viewBox="0 0 600 428" role="img" aria-label="Презумпция внутри механизма защиты, отдельно от защитного результата"><circle cx="208" cy="214" r="191" fill="none" stroke="#c4c7c2" stroke-width="1"/><circle cx="208" cy="214" r="126" fill="none" stroke="#aeb9bf" stroke-width="2"/><path d="M334 214 H420" fill="none" stroke="#aeb9bf" stroke-width="1"/><path d="M435 119 V309 M435 119 H461 M435 309 H461" fill="none" stroke="#151718" stroke-width="2"/>${step>0?'<g class="tool-slot"><path d="M171 319 H245 V352 H171Z" fill="#c28c55"/><path d="M208 319 V288" fill="none" stroke="#c28c55" stroke-width="2"/></g>':''}<path d="M208 23 V41 M17 214 H35 M381 214 H399 M208 387 V405" stroke="#8c969c"/></svg><div class="outer-label">МЕХАНИЗМ ЗАЩИТЫ</div><div class="inner-label">${step===0?'Необходимые<br>условия':'Отдельная<br>предпосылка'}</div><div class="result-label ${step===1?'dim':''}">Защитное<br>средство</div>${step>0?'<div class="tool-label">ПРЕЗУМПЦИЯ</div>':''}</div>`;
  };
  const cabala = step => {
    const proposal=step>=2;
    const title=['Кабальная\nсделка','Трудность\nдоказывания','Предложение\nавтора','Доказанные\nобстоятельства','Предполагается\nиспользование','Состав\nсохраняется'][step];
    const subtitle=['Материально-правовой состав','Использование положения потерпевшего','Прямой презумпции в п. 3 ст. 179 нет','Комплекс фактов-оснований','Один элемент состава','Меняется порядок установления'][step];
    const factLabels=step<3?['Тяжелые обстоятельства','Вынужденность сделки','Крайняя невыгодность','Использование положения']:['Вынужденность вследствие<br>тяжелых обстоятельств','Крайняя невыгодность','Обстоятельства осведомленности','Использование положения'];
    return `<div class="law-badge ${proposal?'proposal':''}">${proposal?'АВТОРСКОЕ ПРЕДЛОЖЕНИЕ · DE LEGE FERENDA':'ДЕЙСТВУЮЩЕЕ ПРАВО · DE LEGE LATA'}</div><div class="number-watermark" aria-hidden="true">179</div><div class="cabala-title"><h1 class="medium"><span class="word-cut">${lines(title)}</span></h1><p>${esc(subtitle)}</p></div><div class="cabala-boundary"></div><div class="case-stack ${step===5?'compact':''}">${factLabels.map((v,i)=>`<div class="case-stratum ${i===3&&step===1?'uncertain':''} ${step>=3&&i<3?'proved':''} ${step>=4&&i===3?'presumed':''}"><span class="n">${String(i+1).padStart(2,'0')}</span><span class="value">${v}</span></div>`).join('')}</div>${step===3||step===4?'<div class="case-legend"><span><i></i>Доказано</span><span><i class="assumption"></i>Предположение</span></div>':''}${step===5?'<div class="rebuttal-note">Опровержение: экономическое основание условий / отсутствие связи с затруднениями</div>':''}`;
  };
  const scope = step => {
    const titles=['Опровержение\nдоказательствами','Определенный\nпредмет','Предел\nпрезюмирования'];
    const note=['Принцип задает нормативные пределы','Поведение либо образующий его элемент','Остальные элементы устанавливаются самостоятельно'];
    return `<div class="scope-copy"><h1 class="medium"><span class="word-cut">${lines(titles[step])}</span></h1></div><div class="scope-bottom">${esc(note[step])}</div><div class="scope-drawing"><div class="scope-axis"><div class="scope-cell ${step>0?'active':''}"></div><div class="scope-cell"></div><div class="scope-cell"></div>${step===0?'<div class="rebuttal-slit retracted"></div>':''}</div><div class="scope-labels"><span class="${step>0?'accent':''}">Поведение</span><span>Убытки</span><span>Причинная<br>связь</span></div></div>`;
  };
  const finale = step => step===0 ? `<p class="definition"><span class="accent">Специальное опровержимое правовое правило,</span> в силу которого доказанность предусмотренных правом фактов-оснований позволяет предполагать недобросовестность конкретного поведения либо образующий ее элемент, возлагая риск неопровержения на указанного правилом участника.</p>` : `<div class="final-copy"><h1 class="large"><span class="word-cut">Обеспечивает применение</span>конкретного<br><span class="serif">защитного средства</span></h1></div><div class="final-crosshair" aria-hidden="true"></div><div class="final-author">Антонов Михаил Александрович<small>Преподаватель кафедры гражданского права · СГЮА</small></div>`;
  const draw=[open,levels,negotiations,boundary,mechanism,cabala,scope,finale];
  function sceneMarkup(scene,step){return `<div class="scene-body">${header(scene,step)}${draw[scene](step)}</div>`;}
  function qaMarkup(n){const q=D.qa[n];return `<div class="scene-body"><div class="scene-eyebrow"><span class="scene-index">Q${String(n+1).padStart(2,'0')}</span><span>${esc(q.title)}</span></div><h1 class="qa-headline ${q.proposal?'accent':''}">${lines(q.headline)}</h1><p class="qa-body ${n===8?'sources':''}">${esc(q.body)}</p><div class="qa-source">${esc(q.source)}</div><div class="scene-line"></div><div class="scene-ref">${esc(q.ref)}</div><div class="scene-page">ВОПРОСЫ</div></div>`;}
  if(new URLSearchParams(location.search).has('print')){document.body.className='reduced print-mode';$('#app').innerHTML=steps.map(t=>`<section class="print-frame"><div class="stage ${theme(t.scene)}">${sceneMarkup(t.scene,t.step)}</div></section>`).join('')+D.qa.map((q,i)=>`<section class="print-frame"><div class="stage qa ${q.proposal?'':'paper'}">${qaMarkup(i)}</div></section>`).join('');return;}
  const isStandalone=!!window.__STANDALONE__;
  const presenter=/\/presenter(?:\/|\.html|$)/.test(location.pathname)||new URLSearchParams(location.search).has('presenter');
  const storageKey='antonov-keynote-2026-state-v2';
  const channelName='antonov-keynote-2026-sync-v2';
  const actor=Math.random().toString(36).slice(2);
  const initial={scene:0,step:0,qa:null,elapsed:0,running:false,startedAt:0,revision:0,actor:'',reduced:false,flat:false};
  const valid=x=>x&&Number.isInteger(x.scene)&&x.scene>=0&&x.scene<D.scenes.length&&Number.isInteger(x.step)&&x.step>=0&&x.step<D.scenes[x.scene].steps.length&&(x.qa===null||Number.isInteger(x.qa)&&x.qa>=0&&x.qa<D.qa.length)&&Number.isFinite(x.elapsed)&&x.elapsed>=0&&Number.isFinite(x.revision)&&Number.isFinite(x.startedAt)&&typeof x.running==='boolean';
  const readSaved=()=>{try{const x=JSON.parse(localStorage.getItem(storageKey));return valid(x)?{...initial,...x}:null;}catch{return null;}};
  let state=readSaved()||{...initial};
  if(new URLSearchParams(location.search).has('reset'))state={...initial};
  let bc=null;try{bc=new BroadcastChannel(channelName);}catch{}
  const peers=new Set();if(window.opener)peers.add(window.opener);
  const elapsed=()=>state.elapsed+(state.running?Math.max(0,Date.now()-state.startedAt)/1000:0);
  let modal=null,lastFocus=null,chromeTimer=0,toastTimer=0,renderKey='',pointerX=0;
  const root=$('#app');
  const toolbar=`<nav class="chrome" aria-label="Управление презентацией"><button data-act="back" aria-label="Предыдущий шаг">←</button><button data-act="next" aria-label="Следующий шаг">→</button><button data-act="presenter" aria-label="Открыть экран докладчика">P</button><button data-act="fullscreen" aria-label="Полный экран">F</button><button data-act="qa" aria-label="Резервные сцены">A</button><button data-act="help" aria-label="Схема управления">H</button></nav>`;
  const shared=`<div class="dialog-backdrop" hidden><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"></section></div><div class="status-toast" role="status" hidden></div><div class="blackout" hidden aria-label="Черный экран"></div>`;
  if(presenter){root.innerHTML=`<div class="presenter"><header class="presenter-header"><div class="presenter-brand">М.А. Антонов <small>Режим докладчика · 10 минут</small></div><div class="presenter-actions"><button data-act="audience">Открыть аудиторию</button><button data-act="qa">Резерв</button><button data-act="help">Управление</button></div></header><div class="presenter-main"><div class="presenter-left"><div><div class="preview-label"><span>Текущий экран</span><span id="current-index"></span></div><div class="preview-wrap current-preview"><div class="stage"></div></div></div><div><div class="preview-label">Следующий смысловой шаг</div><div class="next-brief" id="next-brief"></div></div><div class="next-scene"><div class="preview-label" id="next-scene-label"></div><div class="preview-wrap next-preview"><div class="stage"></div></div></div><div class="scene-jump" aria-label="Перейти к сцене">${D.scenes.map((s,i)=>`<button data-scene="${i}" title="${esc(s.title)}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div><div class="connection-note" id="connection-note">Синхронизация на этом устройстве</div></div><div class="presenter-right"><div class="timing"><div><div class="clock" id="clock">00:00</div><div class="time-label">Фактический таймер</div></div><div><div class="clock secondary" id="plan-clock"></div><div class="time-label">Плановое окно</div></div><div><div class="clock secondary" id="pace"></div><div class="time-label">Отклонение от окна</div></div></div><div><h1 class="notes-heading" id="notes-heading"></h1><p class="notes-origin" id="notes-origin"></p></div><p class="notes-speech" id="notes-speech"></p><div class="notes-cue" id="notes-cue"></div><div class="presenter-navigation"><button data-act="back">Предыдущий шаг</button><button class="primary" data-act="next">Следующий шаг</button><button data-act="timer" id="timer-button">Начать таймер</button><button data-act="reset-timer">Сброс таймера</button><button data-act="home">В начало</button></div></div></div></div>${shared}`;}
  else root.innerHTML=`<div class="viewport"><div class="stage" tabindex="0" role="region" aria-label="Сценическая презентация"></div></div>${toolbar}${shared}`;
  function nextOf(){if(state.qa!==null)return null;const i=steps.indexOf(stepData());return steps[i+1]||null;}
  function updateClock(){if(!presenter)return;const t=stepData(),v=elapsed();$('#clock').textContent=time(v);$('#plan-clock').textContent=state.qa!==null?'Вопросы':time(t.start)+'-'+time(t.start+t.duration);let delta=v<t.start?v-t.start:v>t.start+t.duration?v-t.start-t.duration:0;$('#pace').textContent=state.qa!==null?'-':Math.abs(delta)<1?'В темпе':(delta>0?'+':'-')+time(Math.abs(delta));$('#pace').className='clock secondary '+(delta>0?'late':delta<0?'ahead':'');$('#timer-button').textContent=state.running?'Пауза':'Продолжить';if(v===0&&!state.running)$('#timer-button').textContent='Начать таймер';}
  function fit(){if(presenter){document.querySelectorAll('.preview-wrap').forEach(x=>{const node=x.querySelector('.stage');node.style.transform=`scale(${x.clientWidth/1280})`;});}else{const node=$('.viewport .stage');node.style.transform=`scale(${Math.min(innerWidth/1280,innerHeight/720)})`;}}
  function render(force=false){document.body.classList.toggle('reduced',!!state.reduced);document.body.classList.toggle('flat',!!state.flat);const key=`${state.scene}/${state.step}/${state.qa}/${state.reduced}`;if(key===renderKey&&!force){updateClock();return;}const previous=renderKey.split('/')[0];renderKey=key;const q=state.qa!==null;const cls='stage '+(q?'qa '+(D.qa[state.qa].proposal?'':'paper'):theme(state.scene))+(state.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches?'':' motion')+(previous!==String(state.scene)?' scene-enter':'');const markup=q?qaMarkup(state.qa):sceneMarkup(state.scene,state.step);
    const stage=presenter?$('.current-preview .stage'):$('.viewport .stage');stage.className=cls;stage.dataset.scene=String(state.scene);stage.dataset.step=String(state.step);stage.dataset.qa=state.qa===null?'':String(state.qa);stage.innerHTML=markup;stage.setAttribute('aria-label',q?D.qa[state.qa].title:D.scenes[state.scene].title+' · '+D.scenes[state.scene].steps[state.step].label);document.body.classList.toggle('light',!presenter&&(q?!D.qa[state.qa].proposal:[0,4,7].includes(state.scene)));
    if(presenter){const t=stepData(),next=nextOf();$('#current-index').textContent=q?'Q'+String(state.qa+1).padStart(2,'0'):`${state.scene+1} / 8 · ${state.step+1} / ${D.scenes[state.scene].steps.length}`;$('#notes-heading').textContent=q?D.qa[state.qa].title:D.scenes[state.scene].title;$('#notes-origin').textContent=q?D.qa[state.qa].ref:D.scenes[state.scene].article;$('#notes-speech').textContent=q?D.qa[state.qa].body:t.speech;$('#notes-cue').textContent=q?'Резерв не входит в регламент. Esc возвращает к докладу.':`После фразы ${t.cue} ${next?'нажать один раз.':'остаться на финальном экране.'} Пауза: ${t.pause} сек.`;$('#next-brief').textContent=q?'Esc - вернуться к основной линии':next?D.scenes[next.scene].title+' · '+next.label:'Доклад завершен · A открывает резерв';const ns=q?state.scene:Math.min(state.scene+1,D.scenes.length-1);$('#next-scene-label').textContent=q?'Возврат к основной сцене':state.scene===7?'Финальный экран':'Следующая сцена · '+D.scenes[ns].title;const nextNode=$('.next-preview .stage');nextNode.className='stage '+theme(ns);nextNode.innerHTML=sceneMarkup(ns,ns===7&&state.scene===7?1:0);document.querySelectorAll('[data-scene]').forEach(x=>x.classList.toggle('current',+x.dataset.scene===state.scene));}
    fit();updateClock();
  }
  function emit(){const envelope={protocol:channelName,sender:actor,state};try{bc?.postMessage(envelope);}catch{}for(const p of peers){try{if(p.closed)peers.delete(p);else p.postMessage(envelope,'*');}catch{}}}
  function save(){state.revision=Math.max(state.revision+1,Date.now()*1000);state.actor=actor;try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{}emit();render();}
  function receive(x){if(!valid(x))return;if(x.revision<state.revision||(x.revision===state.revision&&x.actor<=state.actor))return;state={...initial,...x};render();}
  if(bc)bc.onmessage=e=>{const m=e.data;if(m?.protocol!==channelName||m.sender===actor)return;if(m.request){emit();return;}receive(m.state);if(presenter)$('#connection-note').textContent='Экраны синхронизированы';};
  addEventListener('storage',e=>{if(e.key===storageKey&&e.newValue){try{receive(JSON.parse(e.newValue));}catch{}}});
  addEventListener('message',e=>{const m=e.data;if(m?.protocol!==channelName)return;if(!peers.has(e.source)&&e.source!==window.opener)return;if(m.request){emit();return;}receive(m.state);});
  function mutate(fn){const latest=readSaved();if(latest&&(latest.revision>state.revision||latest.revision===state.revision&&latest.actor>state.actor))state=latest;fn();save();}
  function pauseTimer(){state.elapsed=elapsed();state.running=false;state.startedAt=0;}
  function go(scene,step=0){mutate(()=>{state.scene=scene;state.step=step;state.qa=null;});}
  function advance(direction){if(modal)return;if(state.qa!==null){mutate(()=>{state.qa=Math.min(D.qa.length-1,Math.max(0,state.qa+direction));});return;}const i=steps.indexOf(stepData());const n=steps[i+direction];if(n)go(n.scene,n.step);else if(direction>0){mutate(()=>pauseTimer());toast('Доклад завершен · A открывает резерв');}}
  function toast(text){const x=$('.status-toast');x.textContent=text;x.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{x.hidden=true;},2600);}
  function chrome(){const x=$('.chrome');if(!x)return;x.classList.add('show');clearTimeout(chromeTimer);chromeTimer=setTimeout(()=>x.classList.remove('show'),1800);}
  function closeModal(){modal=null;$('.dialog-backdrop').hidden=true;lastFocus?.focus?.();}
  function showModal(kind){if(modal===kind){closeModal();return;}modal=kind;lastFocus=document.activeElement;const d=$('.dialog');$('.dialog-backdrop').hidden=false;
    if(kind==='qa')d.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">Вопросы из зала</h2><button data-act="close-modal">Закрыть · Esc</button></div><div class="qa-grid">${D.qa.map((q,i)=>`<button data-qa="${i}"><small>${i===9?'0':i+1}</small><span>${esc(q.title)}</span></button>`).join('')}</div><p>Резервные сцены не входят в десятиминутный доклад.</p>`;
    else d.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">Управление</h2><button data-act="close-modal">Закрыть · Esc</button></div><dl class="help-grid"><dt>→ · Space · Enter · PageDown</dt><dd>Следующий смысловой шаг</dd><dt>← · PageUp</dt><dd>Предыдущий шаг</dd><dt>F</dt><dd>Полный экран</dd><dt>P</dt><dd>Открыть экран докладчика</dd><dt>T</dt><dd>Начать / приостановить таймер</dd><dt>A · Q</dt><dd>Резервные сцены; 1-9 и 0 выбирают тему</dd><dt>Esc</dt><dd>Закрыть меню / вернуться из резерва</dd><dt>M · G</dt><dd>Сокращенное движение / плоская геометрия</dd><dt>B · .</dt><dd>Черный экран</dd><dt>Home</dt><dd>Первая сцена</dd></dl><p>На втором мониторе открой экран аудитории, перенеси его на проектор и нажми F. Перед началом речи запусти таймер клавишей T. Щелчок или касание экрана также переводит к следующему шагу.</p><div class="help-links"><a href="static/index.html">Статическая версия</a>${isStandalone?'':`<a href="standalone.html" download>Автономный HTML</a><a href="fallback.pdf">PDF</a>`}</div>`;
    d.focus();
  }
  function selectQA(n){closeModal();mutate(()=>{pauseTimer();state.qa=n;});}
  function openPeer(mode){let url;if(isStandalone){url=new URL(location.href);url.search='';if(mode==='presenter')url.searchParams.set('presenter','1');}else url=new URL(mode==='presenter'?'presenter/':'present/',document.baseURI);const child=window.open(url.href,mode==='presenter'?'antonov-presenter':'antonov-audience');if(child){peers.add(child);toast(mode==='presenter'?'Экран докладчика открыт':'Экран аудитории открыт');}else toast('Разреши открытие дополнительного окна для двух экранов');}
  async function full(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Полный экран недоступен; используй F11 в браузере');}}
  function action(name){switch(name){case'next':advance(1);break;case'back':advance(-1);break;case'qa':showModal('qa');break;case'help':showModal('help');break;case'close-modal':closeModal();break;case'fullscreen':full();break;case'presenter':openPeer('presenter');break;case'audience':openPeer('audience');break;case'timer':mutate(()=>{if(state.running)pauseTimer();else{state.running=true;state.startedAt=Date.now();}});break;case'reset-timer':mutate(()=>{state.elapsed=0;state.running=false;state.startedAt=0;});break;case'home':go(0,0);break;case'reduced':mutate(()=>state.reduced=!state.reduced);toast(state.reduced?'Сокращенное движение включено':'Основное движение включено');break;case'flat':mutate(()=>state.flat=!state.flat);toast(state.flat?'Плоская геометрия включена':'Пространственная геометрия включена');break;case'blackout':$('.blackout').hidden=!$('.blackout').hidden;break;}}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(b){action(b.dataset.act);return;}const q=e.target.closest('[data-qa]');if(q){selectQA(+q.dataset.qa);return;}const jump=e.target.closest('[data-scene]');if(jump){go(+jump.dataset.scene);return;}if(e.target.classList.contains('dialog-backdrop')){closeModal();return;}if(!presenter&&!modal&&e.target.closest('.viewport')&&!e.target.closest('a,button'))advance(1);});
  document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select'))return;const k=e.key;if(modal){if(k==='Escape'){e.preventDefault();closeModal();return;}if(modal==='qa'&&/^[0-9]$/.test(k)){e.preventDefault();selectQA(k==='0'?9:+k-1);return;}if(k==='Tab'){const items=[...$('.dialog').querySelectorAll('button,a')];if(items.length){const first=items[0],last=items[items.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.dialog'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}return;}
    if(k==='Escape'&&state.qa!==null){e.preventDefault();mutate(()=>state.qa=null);return;}if((k===' '||k==='Enter')&&e.target.closest('button,a'))return;
    const map={ArrowRight:'next',ArrowLeft:'back',' ':'next',Enter:'next',PageDown:'next',PageUp:'back',Home:'home',f:'fullscreen',F:'fullscreen',p:'presenter',P:'presenter',a:'qa',A:'qa',q:'qa',Q:'qa',h:'help',H:'help',t:'timer',T:'timer',m:'reduced',M:'reduced',g:'flat',G:'flat',b:'blackout',B:'blackout','.':'blackout'};
    if(map[k]){e.preventDefault();action(map[k]);}
  });
  let swiping=false;
  document.addEventListener('pointerdown',e=>{pointerX=e.clientX;swiping=false;});
  document.addEventListener('pointerup',e=>{if(!presenter&&!modal&&e.pointerType==='touch'&&Math.abs(e.clientX-pointerX)>70){swiping=true;advance(e.clientX<pointerX?1:-1);}});
  document.addEventListener('click',e=>{if(swiping){e.stopImmediatePropagation();swiping=false;}},true);
  addEventListener('resize',fit);addEventListener('fullscreenchange',()=>{document.body.dataset.fullscreen=String(!!document.fullscreenElement);fit();});document.addEventListener('mousemove',chrome);
  const observer=new ResizeObserver(fit);if(presenter)document.querySelectorAll('.preview-wrap').forEach(x=>observer.observe(x));
  const timer=setInterval(()=>{if(presenter)updateClock();},250);
  const media=matchMedia('(prefers-reduced-motion: reduce)');media.addEventListener('change',()=>render(true));
  if(new URLSearchParams(location.search).has('flat'))state.flat=true;
  if(new URLSearchParams(location.search).has('reduced'))state.reduced=true;
  render();
  const request={protocol:channelName,sender:actor,request:true};try{bc?.postMessage(request);}catch{}if(window.opener){try{window.opener.postMessage(request,'*');}catch{}}
  addEventListener('beforeunload',()=>{clearInterval(timer);observer.disconnect();try{bc?.close();}catch{}});
  if(!isStandalone&&'serviceWorker' in navigator&&(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1')){navigator.serviceWorker.register(new URL('sw.js',document.baseURI)).catch(()=>{});}
  window.KEYNOTE_API={getState:()=>({...state}),next:()=>advance(1),prev:()=>advance(-1),go,qa:selectQA,action,stepData:()=>({...stepData()}),elapsed,steps,words:()=>({written:steps.reduce((n,t)=>n+words(t.speech),0),spoken:totalWords,pauses,wordsPerMinute:totalWords/((600-pauses)/60)}),sceneMarkup,qaMarkup,closeModal,fit,theme,escape:esc};
})();
